  cierres: t.cierres_listos || [],
  base_dir_dev: t.base_dir_dev,
  usuario_auditor: t.usuario_auditor || null,
};

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_publicacion_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_publicacion_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];
